2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug occurs because the `getopt()` function modifies the contents of the `args` array, specifically changing the value of `args[1]`. This leads to `dev` being assigned an incorrect value after `getopt()` is called, causing failures in the `debugfs.ocfs2` functionality. The fix involves assigning `dev` before calling `getopt()` to ensure it retains the correct value.

        Commit message:
        debugfs.ocfs2: Fix a bug in process_open_args()

In process_open_args(), 'dev' get the wrong value because getopt() will
change the value of args[1]. This problem will cause failure in
debugfs.ocfs2. ocfs2. So we should assign 'dev' before getopt().

This fix fixes the bug introduced in 9693851641bfcd0f2bab226e9f03d9ab05cb7edf

Signed-off-by: Jun Piao <piaojun@huawei.com>
Reviewed-by: Alex Chen <alex.chen@huawei.com>
Signed-off-by: Goldwyn Rodrigues <rgoldwyn@suse.com>
Reported-by: Gang He <ghe@suse.com>  

        Patch:

 static int process_open_args(char **args,
 			     uint64_t *superblock, uint64_t *blocksize)
 {
 	errcode_t ret = 0;
 	uint32_t s = 0;
 	char *ptr, *dev;
 	uint64_t byte_off[OCFS2_MAX_BACKUP_SUPERBLOCKS];
 	uint64_t blksize = 0;
 	int num, argc, c;

 	for (argc = 0; (args[argc]); ++argc);
+	dev = strdup(args[1]);
 	optind = 0;
 	while ((c = getopt(argc, args, "is:")) != EOF) {
 		switch (c) {
 			case 'i':
 				gbls.imagefile = 1;
 				break;
 			case 's':
 				s = strtoul(optarg, &ptr, 0);
 				break;
 			default:
-				return 1;
+				ret = 1;
+				goto bail;
 				break;
 		}
 	}

-	if (!s)
-		return 0;
+	if (!s) {
+		ret = 0;
+		goto bail;
+	}

 	num = ocfs2_get_backup_super_offsets(NULL, byte_off,
 					     ARRAY_SIZE(byte_off));
-	if (!num)
-		return -1;
+	if (!num) {
+		ret = -1;
+		goto bail;
+	}

 	if (s < 1 || s > num) {
 		fprintf(stderr, "Backup super block is outside of valid range"
 			"(between 1 and %d)\n", num);
-		return -1;
+		ret = -1;
+		goto bail;
 	}

-	dev = strdup(args[1]);
 	ret = get_blocksize(dev, byte_off[s-1], &blksize, s);
 	if (ret) {
 		com_err(args[0],ret, "Can't get the blocksize from the device"
 			" by the num %u\n", s);
 		goto bail;
 	}

 	*blocksize = blksize;
 	*superblock = byte_off[s-1]/blksize;
 	ret = 0;
 bail:
 	g_free(dev);
 	return ret;
 }



